#!/bin/bash
# Builds the iOS app (Release configuration, not signed) with the version of app/build.gradle.kts, from the Xcode
# project generated by XcodeGen. The full log goes to ios/xcodebuild.log, which ios-errors.sh reads when the build
# fails. Used by the iOS and the Release workflows; runs from the repository root on macOS.
set -euo pipefail

version=$(sed -n 's/^val _versionName = "\(.*\)"$/\1/p' app/build.gradle.kts)
code=$(sed -n 's/^ *versionCode = \([0-9]*\)$/\1/p' app/build.gradle.kts)
if [ -z "$version" ] || [ -z "$code" ]; then
  echo "::error::_versionName or versionCode not found in app/build.gradle.kts"
  exit 1
fi
echo "Version $version ($code)"
xcodebuild -project ios/Bookmania.xcodeproj -scheme Bookmania -configuration Release \
  -destination 'generic/platform=iOS' -derivedDataPath ios/build \
  MARKETING_VERSION="$version" CURRENT_PROJECT_VERSION="$code" \
  CODE_SIGNING_ALLOWED=NO CODE_SIGNING_REQUIRED=NO CODE_SIGN_IDENTITY="" \
  build > ios/xcodebuild.log 2>&1
tail -5 ios/xcodebuild.log
